using System;using UnityEngine;
[Serializable]public class Curtain261Eye{public int owner,anchorVertex;public Vector2 skinUV;public Vector2[]parent,iris;public Color skinLit,skinShade,lineRGBA;public Vector4 bounds;}
[Serializable]public class Curtain261Design{public Curtain261Eye[]eyes;public string skinMaterial,skinTexture,paletteShader;public string sampling="Explicit original UV anchor, existing ownmaterial lit/shade endpoints; no neighbourcolour",depth="Authored sharedeyeplane, syntheticlid carrier; not originalskinfragment";public float seamArch=.10f,lineHalfWidth=.27f,irisAmplitude=.20f;}
[ExecuteAlways]public sealed class Curtain261View:MonoBehaviour{
 public Walk257View walk;public TextAsset designInput;public ComputeShader curtain;public float closure,irisAmplitude;public bool playing;public float duration=.8f,time;
 Curtain261Design design;public Vector2Int delta;
 public Curtain261Design Design=>design??=JsonUtility.FromJson<Curtain261Design>(designInput.text);
 void OnEnable(){Apply();}void Update(){if(playing){time=(time+Time.unscaledDeltaTime)%duration;closure=Curve(time/duration);}Apply();}
 public static float Curve(float t){if(t<.2f||t>=.9f)return 0;if(t<.45f){float q=(t-.2f)/.25f;return q*q*(3-2*q);}if(t<.55f)return 1;float v=(t-.55f)/.35f;return 1-v*v*(3-2*v);}
 public void Apply(){if(!walk||!designInput||!curtain)return;walk.playing=false;walk.Apply();var eye=walk.Eye;var s=eye.states[0];s.blinkWeight=Mathf.Clamp01(closure);eye.closure=curtain;var cam=walk.Body.viewCamera;
  Vector2 Project(Vector3 w){var q=cam.projectionMatrix*cam.worldToCameraMatrix*new Vector4(w.x,w.y,w.z,1);return new Vector2((q.x/q.w*.5f+.5f)*480,(.5f-q.y/q.w*.5f)*272);}var a=new Vector2[2];for(int i=0;i<2;i++){var e=eye.eyes[i];a[i]=Project(s.head.MultiplyPoint3x4(e.whiteCentreHead))+Project(s.anchors[i])-Project(s.head.MultiplyPoint3x4(e.expectedRestChildHead));}var mean=(a[0]+a[1])*.5f;var reference=(eye.eyes[0].pivotP0+eye.eyes[1].pivotP0)*.5f;delta=new Vector2Int(Mathf.FloorToInt(mean.x-reference.x+.5f),Mathf.FloorToInt(mean.y-reference.y+.5f));curtain.SetInts("_Delta261",delta.x,delta.y);curtain.SetFloat("_IrisAmplitude261",irisAmplitude);curtain.SetFloat("_SeamArch261",Design.seamArch);curtain.SetFloat("_LineWidth261",Design.lineHalfWidth);
  for(int i=0;i<2;i++){var e=Design.eyes[i];Vector4[] Pack(Vector2[]p){var outp=new Vector4[32];for(int k=0;k<p.Length;k++)outp[k]=p[k];return outp;}curtain.SetVectorArray("_Parent261_"+i,Pack(e.parent));curtain.SetVectorArray("_Iris261_"+i,Pack(e.iris));curtain.SetInt("_ParentCount261_"+i,e.parent.Length);curtain.SetInt("_IrisCount261_"+i,e.iris.Length);curtain.SetVector("_Bounds261_"+i,e.bounds);curtain.SetVector("_Skin261_"+i,e.skinLit.linear);curtain.SetVector("_Shade261_"+i,e.skinShade.linear);curtain.SetVector("_Line261_"+i,e.lineRGBA.linear);}
  int kernel=curtain.FindKernel("CloseFromExistingSource");curtain.SetTexture(kernel,"_TemplateRGBA261",eye.templateRGBA);curtain.SetTexture(kernel,"_TemplateRole261",eye.templateRole);walk.source.Apply();
 }
 void OnGUI(){GUI.Box(new Rect(12,12,365,112),"A261 procedural lid / same aperture / art candidate");if(GUI.Button(new Rect(22,42,70,25),playing?"Pause":"Blink"))playing=!playing;closure=GUI.HorizontalSlider(new Rect(105,53,255,15),closure,0,1);GUI.Label(new Rect(22,72,300,20),"Close "+closure.ToString("0.00")+" / iris "+irisAmplitude.ToString("0.00")+" logical px");if(GUI.Button(new Rect(22,96,130,22),"Iris offset 0"))irisAmplitude=0;if(GUI.Button(new Rect(163,96,195,22),"Small return option .20"))irisAmplitude=.20f;}
}
